    '270daily': '27-0 Daily', '270hard': '27-0 Hard Mode', streak: 'Longest Streak',
    bbplus: '25000+', bbexact: 'Exactly 25000', bbspin: '25000 RUNS Team Spin', bbdaily: '25000 RUNS Daily',
