        return '<button type="button" role="tab" aria-selected="' + (x[0] === only) + '" class="ca-seg-btn' + (x[0] === only ? ' is-on' : '') + '" data-ca="adm-sales-kind" data-v="' + x[0] + '">' + x[1] + '</button>';
