    var miss = E.rows.filter(function (r) { return !r.n; }).length;
    if (miss) return 'Pick all 13 starters first (' + miss + ' to go).';
    var seen = {}, dup = E.rows.filter(function (r) { var k = r.n.toLowerCase(), d = seen[k]; seen[k] = 1; return d; })[0];
