    if (!mod.trTo) { mod.trTo = today; mod.trFrom = dayShift(today, -6); }
    mod.trArgs = { metric: metric, range: range, from: custom ? mod.trFrom : null, to: custom ? mod.trTo : null };
    mod.trKey = 'tr_' + metric + '_' + range + (custom ? '_' + mod.trFrom + '_' + mod.trTo : '');
    admFetch(mod.trKey, 'adminTrend', mod.trArgs);
    var X = mod[mod.trKey] || {}, d = X.data;
    // The picker: GA's own metrics, then every event GA has for the range, biggest first, by its real name
    var evs = d && d.events ? gaMerge(site === 'all' ? Object.keys(d.events).map(function (s) { return d.events[s]; }) : [d.events[site]]).sort(function (a, b) { return b.v - a.v; }) : [];
    if (metric.indexOf('event:') === 0 && !evs.some(function (e) { return 'event:' + e.k === metric; })) evs.unshift({ k: metric.slice(6), v: 0 });
    var h = '<div class="ca-ga-controls"><label class="ca-tr-pickrow"><span>Show</span><select id="caTrMetric">' +
      '<optgroup label="Google Analytics Metrics">' + TR_METRICS.map(function (m) { return '<option value="' + m[0] + '"' + (m[0] === metric ? ' selected' : '') + '>' + m[1] + '</option>'; }).join('') + '</optgroup>' +
      (evs.length ? '<optgroup label="Event Count">' + evs.map(function (e) { return '<option value="event:' + esc(e.k) + '"' + ('event:' + e.k === metric ? ' selected' : '') + '>' + esc(e.k) + ' (' + fmt(e.v) + ')</option>'; }).join('') + '</optgroup>' : '') +
      '</select></label>' + admSeg(TR_RANGES, range, 'adm-tr-range') + admSeg([['all', 'Both']].concat(TR_SITES), site, 'adm-tr-site') + '</div>';
    if (custom) h += '<div class="ca-tr-custom"><label>From<input type="date" id="caTrFrom" value="' + mod.trFrom + '" max="' + today + '"></label>' +
      '<label>To<input type="date" id="caTrTo" value="' + mod.trTo + '" max="' + today + '"></label>' +
      '<button type="button" class="ca-btn ca-btn-primary ca-btn-sm" data-ca="adm-tr-go">Show</button></div>' +
      (mod.trErr ? '<p class="ca-lb-err" role="alert">' + esc(mod.trErr) + '</p>' : '') + '<p class="ca-small">Up to 92 days. 2 days or less shows every hour.</p>';
