    var confirming = mod.flagConfirm === f.id, b = function (a, cls, label) { return '<button type="button" class="ca-btn ' + cls + ' ca-btn-sm" data-ca="adm-flag" data-a="' + a + '" data-f="' + esc(f.id) + '">' + label + '</button>'; };
    return f.counted
