      (v.length ? '<ul class="ca-vf-list">' + v.map(function (n) {
        var p = rows[n] || { n: n }, L = p.lg ? logoOf(p.lg) : null, lh = L && L.url ? linkHandle(L.url) : null;
        var note = !mod.vrows ? '' : !p.lg ? 'No logo yet' : !L ? 'Logo' : !lh ? 'Logo, no link yet' : FOLLOW_SITES[L.url.replace(/^https:\/\//, '').split('/')[0]] ? lh.site + ' ' + lh.handle : lh.handle;
        return '<li><button type="button" class="ca-vf-open" data-ca="adm-vf-open" data-n="' + esc(n) + '">' + crest({ n: n, vf: true, c: p.c, lg: p.lg }) +
          '<span class="ca-adm-pn"><b><span class="ca-vf-n">' + esc(n) + '</span>' + TICK + '</b>' + (note ? '<small>' + esc(note) + '</small>' : '') + '</span>' +
          '<span class="ca-vf-edit">Edit</span><span class="ca-lb-go" aria-hidden="true">&rsaquo;</span></button>' +
          '<button type="button" class="ca-link" data-ca="mod-unverify" data-n="' + esc(n) + '">Remove</button></li>';
      }).join('') + '</ul>' : '') + '</div>';
