    if (mod.moreOpen && !e.target.closest('.ca-adm-more')) { mod.moreOpen = false; if (!e.target.closest('[data-ca]')) { render(); return; } }
    var t = e.target.closest('[data-ca]');
    if (!t) return;
    var a = t.getAttribute('data-ca');
