      var k = pmPick(P), C = PM_COPY[k], fin = dmLeft() <= 36e5, r27 = CFG.game === '27-0', free = r27 && promoFreeNow(k);
      var act = free ? 'play' : r27 && canBuyReroll() ? 'pick' : 'play';
