    var fs = prem ? Math.max(7, Math.min(10.5, Math.floor(52 / (0.62 * sur.length + 1.25 * marks + 0.3) * 2) / 2)) : (sur.length + marks * 1.6) <= 7 ? 10.5 : (sur.length + marks * 1.6) <= 8.6 ? 9.5 : 8.5;
