    if (status === 'signed-in' && user && !streakTried && dmWait < 10) { dmWait++; setTimeout(dmMaybe, 1000); return; }
    if (restorePending() || (rrEl && !rrEl.hidden)) { setTimeout(dmMaybe, 3000); return; }
